#!/usr/bin/env bash
#
# Server-side deployment script. The GitLab deploy job scp's this next to the
# generated .env and runs it over ssh:
#
#     ssh user@host "bash /home/<user>/lol/<stack>/deploy.sh"
#
# Everything docker-related happens HERE rather than inside an ssh "..." string,
# so no quoting has to survive a round trip through the CI shell.
#
# Expects, in the same directory:
#   .env             generated by CI — image names, IMAGE_TAG, secrets,
#                    COMPOSE_PROJECT_NAME, STACK
#   .registry.env    generated by CI — a read_registry Deploy Token
#   docker-compose.prod.yml
# and a sibling ../edge/ directory holding the Caddy stack.
#
# Safe to re-run: every step is idempotent. Named volumes are not used — all
# state lives in ./data/, which is never touched here.

set -euo pipefail

cd "$(dirname "$0")"
APP_DIR="$PWD"
EDGE_DIR="$(cd .. && pwd)/edge"

# Values come from a compose .env: no spaces, no '#', no '$' in secrets.
set -a
# shellcheck disable=SC1091
. ./.env
# shellcheck disable=SC1091
. ./.registry.env
set +a

COMPOSE="docker compose -f docker-compose.prod.yml"

echo "=== deploying ${COMPOSE_PROJECT_NAME} (stack=${STACK}) at tag ${IMAGE_TAG}"

# --- shared edge network ------------------------------------------------------
# Both the app stack and the Caddy stack attach to it; created once, kept forever.
docker network inspect lol-edge >/dev/null 2>&1 || docker network create lol-edge

# --- registry login -----------------------------------------------------------
# A Deploy Token, NOT the CI job token: this login is persisted in
# ~/.docker/config.json so `docker compose up -d` still pulls after a reboot,
# long after the pipeline that deployed it has finished.
echo "$REGISTRY_PASSWORD" | docker login -u "$REGISTRY_USER" --password-stdin "$REGISTRY_HOST"

# --- application stack --------------------------------------------------------
echo "--- pulling images"
$COMPOSE pull --quiet

echo "--- starting containers"
# --remove-orphans drops containers left behind by a renamed/removed service.
$COMPOSE up -d --remove-orphans

echo "--- waiting for the backend container"
for _ in $(seq 1 30); do
    state="$(docker inspect -f '{{.State.Running}}' "lol-${STACK}-backend" 2>/dev/null || echo false)"
    [ "$state" = "true" ] && break
    sleep 2
done
if [ "$(docker inspect -f '{{.State.Running}}' "lol-${STACK}-backend" 2>/dev/null || echo false)" != "true" ]; then
    echo "ERROR: lol-${STACK}-backend did not start." >&2
    $COMPOSE logs --tail 50 backend >&2 || true
    exit 1
fi

echo "--- migrations"
# Picks fresh-DB bootstrap vs incremental upgrade, and rotates the app_rw
# password off the migration's dev default. See services/backend/scripts/migrate.sh.
$COMPOSE exec -T backend /app/scripts/migrate.sh

# --- edge (Caddy) -------------------------------------------------------------
echo "--- edge proxy"
cd "$EDGE_DIR"
docker compose -f docker-compose.edge.yml up -d
# Reload rather than restart: picks up this stack's new sites/<stack>.caddy
# without dropping live connections or re-running ACME.
if docker exec lol-caddy caddy reload --config /etc/caddy/Caddyfile --adapter caddyfile; then
    echo "caddy reloaded"
else
    echo "caddy reload failed — restarting the container" >&2
    docker compose -f docker-compose.edge.yml restart caddy
fi

# --- housekeeping -------------------------------------------------------------
cd "$APP_DIR"
docker image prune -f >/dev/null

echo "=== deployed:"
$COMPOSE ps
